import { add, update } from "@/api/endpoint/port";
import { getDictList } from "@/api/dict";
export default {
  name: "PortResAddEdit",
  props: ['fromValue', 'isShow', 'type'],
  data: function data() {
    return {
      submitParams: {},
      rules: {
        port: [{
          required: true,
          message: '接口名称不能为空',
          trigger: 'blur'
        }],
        portType: [{
          required: true,
          message: '接口类型不能为空',
          trigger: 'blur'
        }],
        portAddress: [{
          required: true,
          message: '接口地址不能为空',
          trigger: 'blur'
        }],
        remake: [{
          required: true,
          message: '接口说明不能为空',
          trigger: 'blur'
        }]
      },
      saveLoading: false,
      yesNoList: null,
      showIconChoose: false,
      portTypeList: []
    };
  },
  mounted: function mounted() {
    if (this.type == 'edit') {
      this.submitParams = JSON.parse(JSON.stringify(this.fromValue));
    }
    this.getDict();
  },
  methods: {
    // 获得字典
    getDict: function getDict() {
      var _this = this;
      getDictList("endpoint_port_type").then(function (res) {
        _this.portTypeList = res.data;
      });
    },
    submit: function submit() {
      var _this2 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this2.type == 'add') {
            _this2.saveLoading = true;
            add(_this2.submitParams).then(function (res) {
              if (res.code === 200) {
                _this2.$message.success('添加成功');
              } else {
                _this2.$message.fail('添加失败');
              }
              _this2.saveLoading = false;
              _this2.$emit("close");
              _this2.$emit("refreshData");
            });
          } else if (_this2.type == 'edit') {
            _this2.saveLoading = true;
            update(_this2.submitParams).then(function (res) {
              if (res.code === 200) {
                _this2.$message.success('修改成功');
              } else {
                _this2.$message.fail('修改失败');
              }
              _this2.saveLoading = false;
              _this2.$emit("close");
              _this2.$emit("refreshData");
            });
          }
        }
      });
    },
    chooseClick: function chooseClick(arg) {
      this.submitParams.ciIcon = arg.icon;
    },
    iconClear: function iconClear() {
      this.$forceUpdate();
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    }
  }
};
